import {expect,test,type Page} from '@playwright/test';
async function openLesson78(page:Page){await page.goto('/');const chapterThree=page.locator('.course-chapter-group').nth(2);if(!(await chapterThree.evaluate(element=>(element as HTMLDetailsElement).open)))await chapterThree.locator('summary').click();const lessons=page.locator('.course-lesson-grid > button');await expect(lessons.nth(77)).toContainText('Прямоугольный параллелепипед: грани, рёбра и поверхность');await expect(lessons.nth(77)).toBeEnabled();await expect(lessons.nth(78)).toContainText('Прямоугольный параллелепипед: развёртка и многогранник');await expect(lessons.nth(78)).toBeEnabled();await page.getByRole('button',{name:/Открыть урок 78:/}).click();await page.locator('.lesson-opening-start').click()}
async function jump(page:Page,stageIndex:number){await page.evaluate(stageIndex=>window.dispatchEvent(new CustomEvent('mathnikita-go-to-stage',{detail:{lessonNumber:78,stageIndex}})),stageIndex)}
async function noHorizontalOverflow(page:Page){return page.evaluate(()=>document.documentElement.scrollWidth<=document.documentElement.clientWidth+2)}
test('lesson 78 is usable on iPad, persists retry state and reaches 50-response practice',async({page})=>{test.setTimeout(100_000);await page.addInitScript(()=>localStorage.setItem('mathnikita-mentor-auto-guide','false'));await openLesson78(page);const stage=page.locator('.lesson-runtime:not([hidden]) .interactive-stage[data-stage-id]');await expect(stage).toHaveAttribute('data-stage-id','l78-mission');expect(await noHorizontalOverflow(page)).toBeTruthy();await jump(page,10);await expect(stage).toHaveAttribute('data-stage-id','l78-faces-count');const input=stage.locator('.inline-answer input');for(const wrong of ['5','7']){await input.fill(wrong);await stage.locator('.check-button').click();await expect(stage.locator('.instant-feedback.bad')).toBeVisible()}await expect(stage.getByRole('button',{name:'Дальше →',exact:true})).toBeEnabled();await input.fill('6');await stage.locator('.check-button').click();await expect(stage.locator('.instant-feedback.good')).toBeVisible();const beforeReload=await page.evaluate(()=>JSON.parse(localStorage.getItem('mathnikita-lesson-78-progress-v1')??'null'));expect(beforeReload?.results?.['l78-p7']).toBe(true);await page.reload();await page.getByRole('button',{name:/Открыть урок 78:/}).click();await page.locator('.lesson-opening-start').click();await expect(page.locator('.lesson-runtime:not([hidden]) .interactive-stage')).toHaveAttribute('data-stage-id','l78-faces-count');await jump(page,35);await expect(page.locator('.lesson-runtime:not([hidden]) .interactive-stage')).toHaveAttribute('data-stage-id','l78-summary');await expect(page.locator('.extended-practice')).toHaveAttribute('data-practice-response-count','50');await expect(page.locator('.practice-pythagoras-actions button')).toHaveCount(4);expect(await noHorizontalOverflow(page)).toBeTruthy()});
